/**
 * Blade textures for the hero grass field, inlined as data URIs.
 *
 * The two pmndrs grass-shader textures: the blade diffuse (a vertical green
 * gradient strip) and the blade alpha (the silhouette mask).
 *
 * Inlined rather than referenced as files, on purpose. The alpha cutout is the
 * scene's single point of failure -- the fragment shader does
 *
 *     float alpha = texture2D(alphaMap, vUv).r;
 *     if (alpha < 0.15) discard;
 *
 * so if that texture fails to load it samples as 0, EVERY blade is discarded,
 * and the scene renders as a bare green hill under a perfect sky: geometry
 * intact, grass apparently gone.
 *
 * That is exactly what shipped. These were assets/img/blade_diffuse.jpg and
 * assets/img/blade_alpha.jpg; the build ships WebP only and strips JPEG
 * masters, so both 404'd in production and the whole field vanished.
 *
 * A data URI cannot 404, needs no CORS, and is not tainted under file://.
 * Generated from the repo JPEGs, which are byte-identical to the reference.
 */
export const TEX_DIFFUSE = 'data:image/jpeg;base64,';

export const TEX_ALPHA = 'data:image/jpeg;base64,';

export default { diffuse: TEX_DIFFUSE, alpha: TEX_ALPHA };
